  t[t.Red = 0] = "Red";
  t[t.Yellow = 1] = "Yellow";
  t[t.LightBlue = 2] = "LightBlue";
  t[t.Blue = 3] = "Blue";
  t[t.Green = 4] = "Green";
  t[t.Purple = 5] = "Purple";
