exports.getCarImgByColor = function (t, e) {
  var o;
  var i;
  i = Number(t.name[2]);

  if (t.name.includes("-")) {
    o = 3 + 3 * (i - 1);
  } else {
    if ("2" == t.name[1] || "6" == t.name[1]) {
      o = 1 + 3 * (i - 1);
    } else {
      o = 2 + 3 * (i - 1);
    }
  }

  return t.name.includes("05") ? 6100 + 200 * (i - 1) + e + 1 : t.name.includes("04") ? 6e3 + 200 * (i - 1) + e + 1 : "" + (e + 1 + 100 * o);
};

exports.getCarBodyImgByColor = function (t, e) {
  var o;
  var i;
  i = Number(t.name[2]);

  if (t.name.includes("-")) {
    if (1 == i) {
      o = 11;
    } else {
      if (2 == i) {
        o = 12;
      } else {
        3 == i && (o = 14);
      }
    }
  } else {
    if (1 == i) {
      o = 11;
    } else {
      if (2 == i) {
        o = 13;
      } else {
        3 == i && (o = 15);
      }
    }
  }

  return "" + (e + 1 + 100 * o);
};

